import { ifDef } from "./ifDef";
import { isSubStr } from "./isSubStr";

export type MarkupChunkType = "sub" | "sup";

export type MarkupChunk = {
  type?: MarkupChunkType;
  color?: string;
  fontSizePt?: number;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  overline?: boolean;
  chunks: (MarkupChunk | string)[];
};

export const scanMarkupEnd = (
  text: string,
  start: number,
  stopper: string
): number => {
  let level = 0;
  let pos = start;
  while (pos < text.length) {
    const ch = text[pos++];
    if (ch === stopper && level <= 0) break;
    if (ch === "{") level++;
    else if (ch === "}") level--;
  }
  return pos;
};

type TopParams = Omit<MarkupChunk, "chunks">;

export const parseMarkup = (text: string, top: TopParams = {}): MarkupChunk => {
  let curProps = { ...top };
  const res: MarkupChunk = { ...top, chunks: [] };
  let pos = 0;
  let prevPos = 0;

  const updateLeftText = (lastPos: number) => {
    if (lastPos > prevPos) {
      const chunkText = text.slice(prevPos, lastPos);
      const chunk =
        curProps.color === top.color
          ? chunkText
          : {
              ...curProps,
              chunks: [chunkText],
            };
      res.chunks.push(chunk);
    }
  };

  const getParamValue = (start: number): string | undefined => {
    const stop = text.indexOf("}", start);
    let newValue: string | undefined;
    if (stop < 0) {
      pos = start;
      newValue = undefined;
    } else {
      newValue = text.slice(start, stop);
      pos = stop + 1;
    }
    prevPos = pos;
    return newValue;
  };

  type CmdParams = {
    param?: boolean | "color";
    onChunk: (value?: string) => TopParams;
  };
  const onCmd = (cmdSize: number, { param, onChunk }: CmdParams) => {
    updateLeftText(pos - 1);
    let paramValue: string | undefined;
    if (param) {
      paramValue = getParamValue(pos + cmdSize);
      pos = scanMarkupEnd(text, pos, "}");
    } else {
      prevPos = pos + cmdSize;
    }
    pos = scanMarkupEnd(text, prevPos, "}");
    const chunk = parseMarkup(
      text.slice(prevPos, pos - 1),
      onChunk(paramValue)
    );
    res.chunks.push(chunk);
    prevPos = pos;
  };
  const tryCmd = (cmd: string, params: CmdParams): boolean => {
    if (!isSubStr(text, pos, cmd)) return false;
    onCmd(cmd.length, params);
    return true;
  };

  const addTypedChunk = (type: MarkupChunkType) => {
    updateLeftText(pos - 1);
    let subText = "";
    if (text[pos] === "{") {
      prevPos = pos + 1;
      pos = scanMarkupEnd(text, prevPos, "}");
      subText = text.slice(prevPos, pos - 1);
    } else {
      prevPos = pos;
      pos = prevPos + 1;
      subText = text.slice(prevPos, pos);
    }
    const chunk: MarkupChunk = parseMarkup(subText, { ...top, type });
    res.chunks.push(chunk);
    prevPos = pos;
  };

  /* eslint no-loop-func: "off" */

  while (pos < text.length) {
    const ch = text[pos++];
    if (ch === "^") {
      addTypedChunk("sup");
    } else if (ch === "_") {
      addTypedChunk("sub");
    } else if (ch === "\\") {
      if (isSubStr(text, pos, "color{")) {
        // color for right text
        updateLeftText(pos - 1);
        curProps = { ...curProps, color: getParamValue(pos + 6) };
        continue;
      }
      if (
        tryCmd("textbf{", {
          onChunk: () => ({ ...curProps, bold: true }),
        })
      )
        continue;

      if (
        tryCmd("textit{", {
          onChunk: () => ({ ...curProps, italic: true }),
        })
      )
        continue;

      if (
        tryCmd("underline{", {
          onChunk: () => ({ ...curProps, underline: true }),
        })
      )
        continue;

      if (
        tryCmd("overline{", {
          onChunk: () => ({ ...curProps, overline: true }),
        })
      )
        continue;

      const recSz = Object.entries(sizesMap).find(([key]) =>
        isSubStr(text, pos, `${key}{`)
      );
      if (recSz) {
        const [key, fontSizePt] = recSz;
        onCmd(1 + key.length, {
          onChunk: () => ({ ...curProps, fontSizePt }),
        });
        continue;
      }
    } else if (ch === "{") {
      if (
        tryCmd("\\color{", {
          param: true,
          onChunk: (color) => ({ ...curProps, color }),
        })
      )
        continue;

      if (
        tryCmd("\\textbf ", {
          onChunk: () => ({ ...curProps, bold: true }),
        })
      )
        continue;

      if (
        tryCmd("\\textit ", {
          onChunk: () => ({ ...curProps, italic: true }),
        })
      )
        continue;

      if (
        tryCmd("\\underline ", {
          onChunk: () => ({ ...curProps, underline: true }),
        })
      )
        continue;

      if (
        tryCmd("\\overline ", {
          onChunk: () => ({ ...curProps, overline: true }),
        })
      )
        continue;

      if (
        tryCmd("\\fontsize{", {
          param: true,
          onChunk: (value) => ({
            ...curProps,
            fontSizePt: ifDef(value, (it) => +it),
          }),
        })
      )
        continue;

      const recSz = Object.entries(sizesMap).find(([key]) =>
        isSubStr(text, pos, `\\${key} `)
      );
      if (recSz) {
        const [key, fontSizePt] = recSz;
        onCmd(2 + key.length, {
          onChunk: () => ({ ...curProps, fontSizePt }),
        });
        continue;
      }
    }
  }

  updateLeftText(pos);
  return res;
};

